UPDATE files f SET title = gt.title FROM gt WHERE f.full_code = gt.full_code AND f.title ~* '^(Church Consistory Books, Chernivtsi.*|Church Books, Chernivtsi.*)$';
UPDATE files f SET title = regexp_replace(f.title, '^Метрична книга\. (Метричні книги )', '\1') FROM gt WHERE f.full_code = gt.full_code AND f.title ~ '^Метрична книга\. Метричні книги ';

SELECT 'A created' k, count(*) FROM (SELECT 1) x WHERE false UNION ALL SELECT 'A created', count(*) FROM mf JOIN files f ON f.full_code = 'ДАЧвО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code UNION ALL SELECT 'B tagged', count(*) FROM mt JOIN files f ON f.full_code = mt.full_code WHERE 'метрична книга' = ANY(f.tags) UNION ALL SELECT 'H re-dated', count(*) FROM hf UNION ALL SELECT 'G retitled', count(*) FROM gt JOIN files f ON f.full_code = gt.full_code WHERE f.title = gt.title;
